<?php
/**
 * The Privacyverklaring, the Voorwaarden and the Licenties (39.0,
 * config/legal.php, docs/LEGAL.md) — in the request's language, the same
 * for the website and the app, which both read $data['legal'].
 *
 * The Licenties' package sections are built here: PHPMailer, the website's
 * one package (includes/vendor/phpmailer/VERSION), and every artifact the
 * Android release build ships (config/licenses-android.php, generated by
 * tools/licenses-build.php), grouped by project, each with its licence,
 * source, copyright where it is known, and the licence texts.
 */
declare(strict_types=1);

require_once dirname(__DIR__) . '/includes/i18n.php';

if (!function_exists('legal_documents')) {

    /**
     * @return array{back: string, licence_text: string,
     *               documents: list<array{id: string, label: string, icon: string, title: string, lede: string, sections: list<array>}>}
     */
    function legal_documents(): array
    {
        $copy = config_copy('legal');
        $docs = [];

        foreach ((array) $copy['documents'] as $id => $doc) {
            $sections = array_map('legal_section', (array) $doc['sections']);
            if ($id === 'licenses') {
                $sections = array_merge($sections, legal_license_sections((array) $copy['licenses']));
            }
            $docs[] = [
                'id'       => (string) $id,
                'label'    => (string) $doc['label'],
                'icon'     => (string) $doc['icon'],
                'title'    => (string) $doc['title'],
                'lede'     => (string) $doc['lede'],
                'sections' => $sections,
            ];
        }

        return [
            'back'      => (string) $copy['back'],
            'licence_text' => (string) $copy['licence_text'],
            'documents' => $docs,
        ];
    }

    /** One section in the shape both apps read: every field present. */
    function legal_section(array $s): array
    {
        return [
            'title'   => (string) ($s['title'] ?? ''),
            'text'    => array_values(array_map('strval', (array) ($s['text'] ?? []))),
            'points'  => array_values(array_map('strval', (array) ($s['points'] ?? []))),
            'link'    => isset($s['link']['href']) ? ['label' => (string) $s['link']['label'], 'href' => (string) $s['link']['href']] : null,
            'licence' => isset($s['licence']) ? (string) $s['licence'] : null,
        ];
    }

    /**
     * The projects the Android app's artifacts belong to: which artifacts
     * (a group prefix, or group:name), a name, the source, and the
     * copyright line where the project states one.
     */
    function legal_android_projects(): array
    {
        return [
            ['match' => 'androidx.health.connect:connect-client-external-protobuf', 'name' => 'Protocol Buffers (in Health Connect)',
             'source' => 'https://github.com/protocolbuffers/protobuf', 'copyright' => 'Copyright 2008 Google Inc. All rights reserved.'],
            ['match' => 'androidx.health.connect', 'name' => 'Health Connect',
             'source' => 'https://developer.android.com/jetpack/androidx/releases/health-connect', 'copyright' => 'Copyright The Android Open Source Project'],
            ['match' => 'androidx.', 'name' => 'AndroidX (Jetpack)',
             'source' => 'https://developer.android.com/jetpack/androidx', 'copyright' => 'Copyright The Android Open Source Project'],
            ['match' => 'org.jetbrains.kotlinx', 'name' => 'Kotlin-bibliotheken (kotlinx)',
             'source' => 'https://github.com/Kotlin', 'copyright' => 'Copyright JetBrains s.r.o. and contributors'],
            ['match' => 'org.jetbrains.kotlin', 'name' => 'Kotlin',
             'source' => 'https://github.com/JetBrains/kotlin', 'copyright' => 'Copyright JetBrains s.r.o. and Kotlin Programming Language contributors'],
            ['match' => 'org.jetbrains', 'name' => 'JetBrains Java Annotations',
             'source' => 'https://github.com/JetBrains/java-annotations', 'copyright' => 'Copyright JetBrains s.r.o.'],
            ['match' => 'com.google.android.', 'name' => 'Google Play-services en Inloggen met Google',
             'source' => 'https://developer.android.com/studio/terms', 'copyright' => 'Copyright Google LLC'],
            ['match' => 'com.google.guava', 'name' => 'Guava',
             'source' => 'https://github.com/google/guava', 'copyright' => 'Copyright The Guava Authors'],
            ['match' => 'com.google.errorprone', 'name' => 'Error Prone Annotations',
             'source' => 'https://github.com/google/error-prone', 'copyright' => 'Copyright The Error Prone Authors'],
            ['match' => 'com.google.j2objc', 'name' => 'J2ObjC Annotations',
             'source' => 'https://github.com/google/j2objc', 'copyright' => null],
            ['match' => 'com.google.code.findbugs', 'name' => 'JSR-305 Annotations',
             'source' => 'http://findbugs.sourceforge.net/', 'copyright' => null],
            ['match' => 'org.checkerframework', 'name' => 'Checker Framework Qualifiers',
             'source' => 'https://checkerframework.org', 'copyright' => 'Copyright 2004-present by the Checker Framework developers'],
            ['match' => 'org.jspecify', 'name' => 'JSpecify',
             'source' => 'https://jspecify.dev', 'copyright' => 'Copyright The JSpecify Authors'],
        ];
    }

    /** The licence names as people read them, by SPDX identifier. */
    function legal_licence_names(): array
    {
        return [
            'Apache-2.0'          => 'Apache License 2.0',
            'LGPL-2.1'            => 'GNU Lesser General Public License 2.1',
            'BSD-3-Clause'        => 'BSD 3-Clause License',
            'MIT'                 => 'MIT License',
            'Android-SDK-License' => 'Android Software Development Kit License',
        ];
    }

    /**
     * A licence text as it reads on a phone: its words unchanged, each
     * paragraph one line (the files are wrapped at 80 columns and indented
     * for a terminal), a blank line between paragraphs.
     */
    function legal_reflow(string $text): string
    {
        $paragraphs = preg_split('/\R\s*\R/', trim(str_replace("\f", '', $text)));
        $paragraphs = array_map(static fn ($p) => trim((string) preg_replace('/\s+/', ' ', $p)), $paragraphs);

        return implode("\n\n", array_filter($paragraphs, static fn ($p) => $p !== ''));
    }

    /** The package sections and the licence texts. */
    function legal_license_sections(array $c): array
    {
        $names    = legal_licence_names();
        $sections = [];
        $used     = [];

        /* The website: PHPMailer, vendored (includes/vendor/phpmailer/VERSION). */
        $vendor  = dirname(__DIR__) . '/includes/vendor/phpmailer/VERSION';
        $version = is_file($vendor) && preg_match('/PHPMailer v([0-9.]+)/', (string) file_get_contents($vendor), $m) ? $m[1] : null;
        if ($version !== null) {
            $sections[] = legal_section([
                'title'  => (string) $c['website'] . ' · PHPMailer',
                'text'   => [sprintf((string) $c['licence'], $names['LGPL-2.1']),
                             'Copyright 2012 - 2020 Marcus Bointon, 2010 - 2012 Jim Jagielski, 2004 - 2009 Andy Prevost; original author Brent R. Matzelle'],
                'points' => ['phpmailer/phpmailer ' . $version],
                'link'   => ['label' => (string) $c['source'], 'href' => 'https://github.com/PHPMailer/PHPMailer'],
            ]);
            $used['LGPL-2.1'] = true;
        }

        /* The Android app: its artifacts, by project. */
        $file      = dirname(__DIR__) . '/config/licenses-android.php';
        $artifacts = is_file($file) ? (array) require $file : [];
        $groups    = [];
        foreach ($artifacts as $a) {
            $coordinate = $a['group'] . ':' . $a['name'];
            foreach (legal_android_projects() as $i => $project) {
                if (str_starts_with($coordinate, $project['match'])) {
                    $groups[$i][$a['licence']][] = $coordinate . ' ' . $a['version'];
                    break;
                }
            }
        }
        ksort($groups);

        foreach ($groups as $i => $byLicence) {
            $project = legal_android_projects()[$i];
            foreach ($byLicence as $licence => $points) {
                $used[$licence] = true;
                $text = [sprintf((string) $c['licence'], $names[$licence] ?? $licence)];
                if ($project['copyright'] !== null) {
                    $text[] = $project['copyright'];
                }
                $sections[] = legal_section([
                    'title'  => (string) $c['app'] . ' · ' . t($project['name']) . ' · ' . tn(count($points), ...(array) $c['packages']),
                    'text'   => $text,
                    'points' => $points,
                    'link'   => ['label' => (string) $c['source'], 'href' => $project['source']],
                ]);
            }
        }

        /* The texts themselves, for every licence the lists use. */
        $files = [
            'Apache-2.0'   => dirname(__DIR__) . '/config/licenses/apache-2.0.txt',
            'LGPL-2.1'     => dirname(__DIR__) . '/includes/vendor/phpmailer/LICENSE',
            'BSD-3-Clause' => dirname(__DIR__) . '/config/licenses/bsd-3-clause.txt',
            'MIT'          => dirname(__DIR__) . '/config/licenses/mit.txt',
        ];
        foreach ($files as $licence => $path) {
            if (isset($used[$licence]) && is_file($path)) {
                $sections[] = legal_section([
                    'title'   => (string) $c['texts'] . ' · ' . $names[$licence],
                    'licence' => legal_reflow((string) file_get_contents($path)),
                ]);
            }
        }
        if (isset($used['Android-SDK-License'])) {
            $sections[] = legal_section([
                'title' => (string) $c['texts'] . ' · ' . $names['Android-SDK-License'],
                'text'  => [(string) $c['sdk_note']],
                'link'  => ['label' => (string) $c['source'], 'href' => 'https://developer.android.com/studio/terms'],
            ]);
        }

        return $sections;
    }
}
